package org.localvoice.tts;

import java.io.*;
import java.nio.file.*;
import java.security.MessageDigest;
import java.util.*;
import java.util.concurrent.atomic.AtomicBoolean;

/** Actual production helper with explicit fake FD identities; not an Android fstat test. */
public final class FreshVerificationCheck {
    @org.junit.Test public void check() throws Exception { main(new String[0]); }
    interface Action {void run()throws Exception;}
    static int passed,skipped;
    static final byte[] PAYLOAD=new byte[1024*1024+31];
    static {new Random(111).nextBytes(PAYLOAD);}
    static final class Skip extends Exception {Skip(String message){super(message);}}
    static void require(boolean ok,String why){if(!ok)throw new AssertionError(why);}
    static void rejects(Action action)throws Exception{try{action.run();throw new AssertionError("Expected IOException");}catch(IOException expected){}}
    static void test(String name,Action action)throws Exception{try{action.run();passed++;System.out.println("PASS "+name);}catch(Skip unavailable){skipped++;System.out.println("SKIP "+name+": "+unavailable.getMessage());}}
    static String hash(byte[] bytes)throws Exception{StringBuilder out=new StringBuilder();for(byte b:MessageDigest.getInstance("SHA-256").digest(bytes))out.append(String.format(Locale.ROOT,"%02x",b&255));return out.toString();}
    static String wrong(String pin){return (pin.charAt(0)=='0'?"1":"0")+pin.substring(1);}
    static final class Node {final String inode;long revision;boolean precise=true,regular=true,sealCandidate,sealed;Node(String inode){this.inode=inode;}}
    static final class Identity implements ModelFiles.StatReader {
        final Map<String,Node> nodes=new HashMap<>();int sequence;
        Node node(File file){return nodes.computeIfAbsent(file.getAbsolutePath(),k->new Node("inode-"+(++sequence)));}
        public ModelFiles.Stamp read(File file)throws IOException{if(!file.exists())throw new FileNotFoundException();return stamp(node(file),file.length());}
        ModelFiles.Stamp stamp(Node node,long size){return new ModelFiles.Stamp(size,node.inode+":"+node.revision,node.regular,false,node.precise,node.sealCandidate,node.sealed);}
    }
    static final class Opener implements ModelFiles.FileOpener {
        final Identity identity;int opens,live,closes,seals;boolean unavailable,wrongDescriptor,closeFailure,sealUnavailable,sealFailure,statFailureAfterSeal;InputStream overrideInput;
        final List<Held> handles=new ArrayList<>();
        Opener(Identity identity){this.identity=identity;}
        public ModelFiles.HeldFile open(File file)throws IOException{
            opens++;if(unavailable)return null;Node node=wrongDescriptor?new Node("different-descriptor"):identity.node(file);
            Held held=new Held(file,node);handles.add(held);live++;return held;
        }
        final class Held implements ModelFiles.HeldFile {
            final FileInputStream input;final InputStream observed;final Node node;final long size;boolean closed;
            Held(File file,Node node)throws IOException{this.input=new FileInputStream(file);this.observed=overrideInput==null?input:overrideInput;this.node=node;this.size=file.length();}
            public InputStream input(){return observed;}
            public ModelFiles.Stamp stamp()throws IOException{if(closed)throw new IOException("Descriptor closed");if(statFailureAfterSeal&&node.sealed)throw new IOException("Injected post-seal stat failure");return identity.stamp(node,size);}
            public boolean seal()throws IOException{seals++;if(sealFailure)throw new IOException("Injected seal failure");if(sealUnavailable)return false;node.sealed=true;node.revision++;return true;}
            public void close()throws IOException{if(!closed){closed=true;live--;closes++;try{input.close();}finally{if(observed!=input)observed.close();}if(closeFailure)throw new IOException("Injected descriptor close failure");}}
        }
    }
    static final class Fixture implements AutoCloseable {
        final File root,stage;final Identity identity=new Identity();final Opener opener=new Opener(identity);
        Fixture()throws IOException{root=Files.createTempDirectory("localvoice-fresh-").toFile().getCanonicalFile();stage=new File(root,"model.download");require(stage.mkdir(),"stage created");}
        File file(String name)throws IOException{File file=new File(stage,name);Files.write(file.toPath(),PAYLOAD);identity.node(file);return file;}
        ModelFiles.FreshVerification job(String revision){return new ModelFiles.FreshVerification(stage,revision,identity,opener);}
        public void close()throws Exception{for(Opener.Held held:opener.handles)try{held.close();}catch(IOException ignored){}Path anchor=root.toPath().toAbsolutePath().normalize();try(java.util.stream.Stream<Path> paths=Files.walk(anchor)){for(Path path:(Iterable<Path>)paths.sorted(Comparator.reverseOrder())::iterator){require(path.toAbsolutePath().normalize().startsWith(anchor),"cleanup boundary");Files.deleteIfExists(path);}}}
    }
    static void mutate(File file,Identity identity)throws Exception{long time=file.lastModified();try(RandomAccessFile out=new RandomAccessFile(file,"rw")){int first=out.read();out.seek(0);out.write(first^1);}require(file.setLastModified(time),"mtime restored");identity.node(file).revision++;}
    public static void main(String[] args)throws Exception{
        final String pin=hash(PAYLOAD);
        test("fresh precise job performs one stored-byte hash and keeps held identity",()->{try(Fixture f=new Fixture();ModelFiles.FreshVerification job=f.job("r1")){File file=f.file("one.bin");StorageMetrics.start();require(job.verifyFresh(file,PAYLOAD.length,pin,()->false,n->{}),"proof created");require(job.accepts(file,PAYLOAD.length,pin),"final proof accepted");require(StorageMetrics.HASH_BYTES.value.get()==PAYLOAD.length&&StorageMetrics.HASH_FILES.value.get()==1&&StorageMetrics.STREAM_HASH_BYTES.value.get()==0,"exactly one disk digest, no stream digest");StorageMetrics.finish();require(f.opener.live==1,"FD remains bound until close");}});
        test("generic young/weak records never gain job-certificate trust",()->{try(Fixture f=new Fixture()){File file=f.file("one.bin");ModelFiles.VerificationCache cache=new ModelFiles.VerificationCache(f.identity);StorageMetrics.start();require(cache.verified(file,PAYLOAD.length,pin,"r1",()->false,n->{}),"first hash");require(cache.verified(file,PAYLOAD.length,pin,"r1",()->false,n->{}),"second hash");require(StorageMetrics.HASH_BYTES.value.get()==2L*PAYLOAD.length,"generic weak identity still fully rehashes");StorageMetrics.finish();}});
        test("coarse fresh seal hashes stored bytes once and never promotes generic cache",()->{try(Fixture f=new Fixture();ModelFiles.FreshVerification job=f.job("r1")){File file=f.file("sealed.bin");Node node=f.identity.node(file);node.precise=false;node.sealCandidate=true;StorageMetrics.start();require(job.verifyFresh(file,PAYLOAD.length,pin,()->false,n->{}),"separately sealed proof");require(f.opener.seals==1&&node.sealed&&job.accepts(file,PAYLOAD.length,pin),"FD seal followed by final mode check");require(StorageMetrics.HASH_BYTES.value.get()==PAYLOAD.length&&StorageMetrics.STREAM_HASH_BYTES.value.get()==0,"one stored SHA");ModelFiles.VerificationCache cache=new ModelFiles.VerificationCache(f.identity);require(cache.verified(file,PAYLOAD.length,pin,"r1",()->false,n->{})&&cache.verified(file,PAYLOAD.length,pin,"r1",()->false,n->{}),"generic still checks bytes");require(StorageMetrics.HASH_BYTES.value.get()==3L*PAYLOAD.length,"coarse sealed certificate cannot promote generic cache");StorageMetrics.finish();}});
        test("absent or failed seal falls back without hashing or retaining descriptor",()->{for(boolean failure:new boolean[]{false,true})try(Fixture f=new Fixture();ModelFiles.FreshVerification job=f.job("r1")){File file=f.file("one.bin");Node node=f.identity.node(file);node.precise=false;node.sealCandidate=true;f.opener.sealFailure=failure;f.opener.sealUnavailable=!failure;StorageMetrics.start();require(!job.verifyFresh(file,PAYLOAD.length,pin,()->false,n->{}),"seal unavailable fallback");require(f.opener.seals==1&&f.opener.live==0&&StorageMetrics.HASH_BYTES.value.get()==0,"no hash or partial proof");require(!job.accepts(file,PAYLOAD.length,pin),"no certificate");StorageMetrics.finish();}});
        test("unsupported API future owner or link eligibility never attempts a coarse seal",()->{for(String reason:new String[]{"API26","future timestamp","other owner","multiple links"})try(Fixture f=new Fixture();ModelFiles.FreshVerification job=f.job("r1")){File file=f.file("one.bin");Node node=f.identity.node(file);node.precise=false;node.sealCandidate=false;require(!job.verifyFresh(file,PAYLOAD.length,pin,()->false,n->{}),reason+" fallback");require(f.opener.opens==0&&f.opener.seals==0,"ineligible metadata never opens or seals");}});
        test("coarse seal mode reversion rejects final proof even with identical timestamps",()->{try(Fixture f=new Fixture();ModelFiles.FreshVerification job=f.job("r1")){File file=f.file("one.bin");Node node=f.identity.node(file);node.precise=false;node.sealCandidate=true;require(job.verifyFresh(file,PAYLOAD.length,pin,()->false,n->{}),"sealed proof");node.sealed=false;rejects(()->job.accepts(file,PAYLOAD.length,pin));require(!new File(f.stage,"installed.manifest").exists(),"mode failure cannot advertise a model");}});
        test("post-seal stat failure closes FD and cannot mint a proof",()->{try(Fixture f=new Fixture();ModelFiles.FreshVerification job=f.job("r1")){File file=f.file("one.bin");Node node=f.identity.node(file);node.precise=false;node.sealCandidate=true;f.opener.statFailureAfterSeal=true;rejects(()->job.verifyFresh(file,PAYLOAD.length,pin,()->false,n->{}));require(f.opener.live==0&&!job.accepts(file,PAYLOAD.length,pin),"failed identity closes and has no proof");}});
        test("sealed job close failure retires every proof before publication",()->{try(Fixture f=new Fixture()){ModelFiles.FreshVerification job=f.job("r1");for(String name:new String[]{"first.bin","last.bin"}){File file=f.file(name);Node node=f.identity.node(file);node.precise=false;node.sealCandidate=true;require(job.verifyFresh(file,PAYLOAD.length,pin,()->false,n->{}),"sealed proof");}f.opener.closeFailure=true;rejects(job::close);require(f.opener.live==0&&f.opener.closes==2&&!new File(f.stage,"installed.manifest").exists(),"all handles attempted and no receipt");rejects(()->job.accepts(new File(f.stage,"first.bin"),PAYLOAD.length,pin));}});
        test("sealed proof cannot escape job retirement or cancellation",()->{try(Fixture f=new Fixture()){File file=f.file("one.bin");Node node=f.identity.node(file);node.precise=false;node.sealCandidate=true;ModelFiles.FreshVerification job=f.job("r1");require(job.verifyFresh(file,PAYLOAD.length,pin,()->false,n->{}),"sealed proof");try(ModelFiles.FreshVerification next=f.job("r1")){require(!next.accepts(file,PAYLOAD.length,pin),"same revision another job cannot inherit");}job.close();rejects(()->job.accepts(file,PAYLOAD.length,pin));try(ModelFiles.FreshVerification cancelled=f.job("r1")){AtomicBoolean stop=new AtomicBoolean();rejects(()->cancelled.verifyFresh(file,PAYLOAD.length,pin,stop::get,n->stop.set(true)));require(f.opener.live==0&&!new File(f.stage,"installed.manifest").exists(),"cancelled sealed hash closes and does not publish");}}});
        test("small files defer checksum rather than minting a certificate",()->{try(Fixture f=new Fixture();ModelFiles.FreshVerification job=f.job("r1")){File file=f.file("one.bin");StorageMetrics.start();require(!job.verifyFresh(file,1024,pin,()->false,n->{}),"small fallback");require(f.opener.opens==0&&StorageMetrics.HASH_BYTES.value.get()==0,"no eager hash or descriptor");StorageMetrics.finish();}});
        test("coarse API26-like identical metadata falls back and rejects changed bytes",()->{try(Fixture f=new Fixture();ModelFiles.FreshVerification job=f.job("r1")){File file=f.file("one.bin");f.identity.node(file).precise=false;require(!job.verifyFresh(file,PAYLOAD.length,pin,()->false,n->{}),"coarse fallback");long time=file.lastModified();try(RandomAccessFile out=new RandomAccessFile(file,"rw")){out.write(PAYLOAD[0]^1);}require(file.setLastModified(time),"mtime restored");require(!new ModelFiles.VerificationCache(f.identity).verified(file,PAYLOAD.length,pin,"r1",()->false,n->{}),"identical weak metadata cannot hide corruption");require(f.opener.opens==0,"no coarse FD proof");}});
        test("unavailable descriptor falls back without a partial hash",()->{try(Fixture f=new Fixture();ModelFiles.FreshVerification job=f.job("r1")){File file=f.file("one.bin");f.opener.unavailable=true;StorageMetrics.start();require(!job.verifyFresh(file,PAYLOAD.length,pin,()->false,n->{}),"EMFILE-style fallback");require(StorageMetrics.HASH_BYTES.value.get()==0&&f.opener.live==0,"no leaked or partial proof");StorageMetrics.finish();}});
        test("wrong descriptor identity is rejected before hashing",()->{try(Fixture f=new Fixture();ModelFiles.FreshVerification job=f.job("r1")){File file=f.file("one.bin");f.opener.wrongDescriptor=true;StorageMetrics.start();rejects(()->job.verifyFresh(file,PAYLOAD.length,pin,()->false,n->{}));require(StorageMetrics.HASH_BYTES.value.get()==0&&f.opener.live==0,"wrong fd not hashed or retained");StorageMetrics.finish();}});
        test("mutation after a hashed prefix with restored mtime rejects the certificate",()->{try(Fixture f=new Fixture();ModelFiles.FreshVerification job=f.job("r1")){File file=f.file("one.bin");AtomicBoolean changed=new AtomicBoolean();rejects(()->job.verifyFresh(file,PAYLOAD.length,pin,()->false,n->{if(changed.compareAndSet(false,true))try{mutate(file,f.identity);}catch(Exception e){throw new RuntimeException(e);}}));require(f.opener.live==0,"failed verification closes FD");}});
        test("post-verification same-size restored-mtime edit fails final barrier",()->{try(Fixture f=new Fixture();ModelFiles.FreshVerification job=f.job("r1")){File file=f.file("one.bin");require(job.verifyFresh(file,PAYLOAD.length,pin,()->false,n->{}),"proof");mutate(file,f.identity);rejects(()->job.accepts(file,PAYLOAD.length,pin));}});
        test("path lookup replacement cannot borrow original held FD identity",()->{try(Fixture f=new Fixture();ModelFiles.FreshVerification job=f.job("r1")){File file=f.file("one.bin");require(job.verifyFresh(file,PAYLOAD.length,pin,()->false,n->{}),"proof");f.identity.nodes.put(file.getAbsolutePath(),new Node("replacement-path"));rejects(()->job.accepts(file,PAYLOAD.length,pin));}});
        test("earlier-file mutation during later verification fails whole-model barrier",()->{try(Fixture f=new Fixture();ModelFiles.FreshVerification job=f.job("r1")){File first=f.file("first.bin"),last=f.file("last.bin");require(job.verifyFresh(first,PAYLOAD.length,pin,()->false,n->{}),"first proof");AtomicBoolean changed=new AtomicBoolean();require(job.verifyFresh(last,PAYLOAD.length,pin,()->false,n->{if(changed.compareAndSet(false,true))try{mutate(first,f.identity);}catch(Exception e){throw new RuntimeException(e);}}),"last proof");rejects(()->job.accepts(first,PAYLOAD.length,pin));}});
        test("wrong hash/size/path/job/revision never inherits a certificate",()->{try(Fixture f=new Fixture();ModelFiles.FreshVerification first=f.job("r1");ModelFiles.FreshVerification second=f.job("r2");ModelFiles.FreshVerification sameRevision=f.job("r1")){File file=f.file("one.bin"),other=f.file("other.bin");require(first.verifyFresh(file,PAYLOAD.length,pin,()->false,n->{}),"first job proof");rejects(()->first.accepts(file,PAYLOAD.length,wrong(pin)));rejects(()->first.accepts(file,PAYLOAD.length-1,pin));require(!first.accepts(other,PAYLOAD.length,pin)&&!second.accepts(file,PAYLOAD.length,pin)&&!sameRevision.accepts(file,PAYLOAD.length,pin),"path and same/different revision jobs cannot inherit");}});
        test("held-file growth is bounded to expected bytes plus one and closes proof",()->{try(Fixture f=new Fixture();ModelFiles.FreshVerification job=f.job("r1")){File file=f.file("one.bin");AtomicBoolean grew=new AtomicBoolean();StorageMetrics.start();rejects(()->job.verifyFresh(file,PAYLOAD.length,pin,()->false,n->{if(grew.compareAndSet(false,true))try{Files.write(file.toPath(),new byte[]{1},StandardOpenOption.APPEND);}catch(IOException e){throw new UncheckedIOException(e);}}));require(StorageMetrics.HASH_BYTES.value.get()<=PAYLOAD.length+1L&&f.opener.live==0,"growth read bounded and FD closed");StorageMetrics.finish();}});
        test("held-file seventeen zero reads fail without a retained descriptor",()->{try(Fixture f=new Fixture();ModelFiles.FreshVerification job=f.job("r1")){File file=f.file("one.bin");java.util.concurrent.atomic.AtomicInteger reads=new java.util.concurrent.atomic.AtomicInteger();f.opener.overrideInput=new InputStream(){public int read(){return 0;}public int read(byte[] b,int o,int n){reads.incrementAndGet();return 0;}};rejects(()->job.verifyFresh(file,PAYLOAD.length,pin,()->false,n->{}));require(reads.get()==17&&f.opener.live==0,"zero-read loop bounded");}});
        test("held-file read failure after prefix cannot mint a certificate",()->{try(Fixture f=new Fixture();ModelFiles.FreshVerification job=f.job("r1")){File file=f.file("one.bin");f.opener.overrideInput=new InputStream(){boolean first=true;public int read()throws IOException{throw new IOException("Injected read failure");}public int read(byte[] b,int o,int n)throws IOException{if(!first)throw new IOException("Injected read failure after prefix");first=false;int count=Math.min(n,65536);System.arraycopy(PAYLOAD,0,b,o,count);return count;}};rejects(()->job.verifyFresh(file,PAYLOAD.length,pin,()->false,n->{}));require(f.opener.live==0&&!job.accepts(file,PAYLOAD.length,pin),"failed read closes and has no proof");}});
        test("cancellation before opening and during hashing closes every FD",()->{try(Fixture f=new Fixture();ModelFiles.FreshVerification job=f.job("r1")){File file=f.file("one.bin");rejects(()->job.verifyFresh(file,PAYLOAD.length,pin,()->true,n->{}));require(f.opener.opens==0,"pre-cancel does not open");AtomicBoolean cancel=new AtomicBoolean();rejects(()->job.verifyFresh(file,PAYLOAD.length,pin,cancel::get,n->cancel.set(true)));require(f.opener.live==0,"during-hash cancel closes");}});
        test("bad checksum cannot leave a held proof",()->{try(Fixture f=new Fixture();ModelFiles.FreshVerification job=f.job("r1")){File file=f.file("one.bin");rejects(()->job.verifyFresh(file,PAYLOAD.length,wrong(pin),()->false,n->{}));require(f.opener.live==0&&!job.accepts(file,PAYLOAD.length,pin),"bad hash has no proof");}});
        test("descriptor cap sixteen defers seventeenth with no extra hash",()->{try(Fixture f=new Fixture();ModelFiles.FreshVerification job=f.job("r1")){StorageMetrics.start();for(int i=0;i<16;i++)require(job.verifyFresh(f.file("file"+i),PAYLOAD.length,pin,()->false,n->{}),"proof "+i);long bytes=StorageMetrics.HASH_BYTES.value.get();require(!job.verifyFresh(f.file("file16"),PAYLOAD.length,pin,()->false,n->{}),"cap fallback");require(f.opener.live==16&&f.opener.opens==16&&StorageMetrics.HASH_BYTES.value.get()==bytes,"bounded descriptors and hash");StorageMetrics.finish();job.close();require(f.opener.live==0,"all sixteen released");}});
        test("close failure still closes all proofs and permanently invalidates job",()->{try(Fixture f=new Fixture()){ModelFiles.FreshVerification job=f.job("r1");File file=f.file("first.bin");job.verifyFresh(file,PAYLOAD.length,pin,()->false,n->{});job.verifyFresh(f.file("last.bin"),PAYLOAD.length,pin,()->false,n->{});f.opener.closeFailure=true;rejects(job::close);require(f.opener.live==0&&f.opener.closes==2,"all close attempts made");rejects(()->job.accepts(file,PAYLOAD.length,pin));rejects(()->job.verifyFresh(file,PAYLOAD.length,pin,()->false,n->{}));}});
        test("closed job cannot validate a moved/activated certificate",()->{try(Fixture f=new Fixture()){ModelFiles.FreshVerification job=f.job("r1");File file=f.file("one.bin");job.verifyFresh(file,PAYLOAD.length,pin,()->false,n->{});job.close();File installed=new File(f.root,"model");ModelFiles.activate(f.stage,installed);rejects(()->job.accepts(new File(installed,"one.bin"),PAYLOAD.length,pin));}});
        test("fresh timestamp eligibility rejects rounded/future/overflow values",()->{require(ModelFiles.preciseFresh(10,1,10000),"precise current millisecond");require(!ModelFiles.preciseFresh(10,0,20000)&&!ModelFiles.preciseFresh(10,123000,20000),"second/microsecond rounded");require(!ModelFiles.preciseFresh(21,1,20000)&&!ModelFiles.preciseFresh(Long.MAX_VALUE,1,20000)&&!ModelFiles.preciseFresh(-1,1,20000),"future/overflow/negative");});
        test("exclusive stored copy hashes nothing and retains fsync",()->{try(Fixture f=new Fixture()){File file=new File(f.stage,"copy.bin");StorageMetrics.start();DownloadFile.copyStored(new ByteArrayInputStream(PAYLOAD),file,PAYLOAD.length,()->false,n->{});require(Arrays.equals(Files.readAllBytes(file.toPath()),PAYLOAD),"exact stored bytes");require(StorageMetrics.STREAM_HASH_BYTES.value.get()==0&&StorageMetrics.HASH_BYTES.value.get()==0&&StorageMetrics.SYNC_CALLS.value.get()==1,"copy defers digest and fsyncs once");StorageMetrics.finish();rejects(()->DownloadFile.copyStored(new ByteArrayInputStream(new byte[1]),file,1,()->false,n->{}));require(file.length()==PAYLOAD.length,"CREATE_NEW preserves existing file");}});
        test("stored-copy truncate/oversize/zero-read/provider failure remain unverified",()->{try(Fixture f=new Fixture()){rejects(()->DownloadFile.copyStored(new ByteArrayInputStream(new byte[2]),new File(f.stage,"short"),3,()->false,n->{}));rejects(()->DownloadFile.copyStored(new ByteArrayInputStream(new byte[3]),new File(f.stage,"long"),2,()->false,n->{}));rejects(()->DownloadFile.copyStored(new InputStream(){public int read(){return 0;}public int read(byte[] b,int o,int n){return 0;}},new File(f.stage,"zero"),1,()->false,n->{}));rejects(()->DownloadFile.copyStored(new InputStream(){public int read()throws IOException{throw new IOException("provider failed");}},new File(f.stage,"failed"),1,()->false,n->{}));require(!new File(f.stage,"installed.manifest").exists(),"no receipt from failed copy");}});
        test("stored-copy cancellation and low-space gate never mint readiness",()->{try(Fixture f=new Fixture()){AtomicBoolean cancel=new AtomicBoolean();File file=new File(f.stage,"cancel");rejects(()->DownloadFile.copyStored(new ByteArrayInputStream(PAYLOAD),file,PAYLOAD.length,cancel::get,n->cancel.set(true)));require(file.delete(),"cancelled writer is closed and deletable");rejects(()->DownloadFile.requireSpace(PAYLOAD.length-1,PAYLOAD.length,0));require(!new File(f.stage,"installed.manifest").exists(),"no receipt");}});
        test("force failure closes writer and leaves no successful verification before retry",()->{try(Fixture f=new Fixture()){File file=new File(f.stage,"sync-failed");java.util.concurrent.atomic.AtomicReference<java.nio.channels.FileChannel> captured=new java.util.concurrent.atomic.AtomicReference<>();StorageMetrics.start();rejects(()->DownloadFile.copyStored(new ByteArrayInputStream(PAYLOAD),file,PAYLOAD.length,()->false,n->{},channel->{captured.set(channel);throw new IOException("Injected force/writeback failure");}));require(captured.get()!=null&&!captured.get().isOpen(),"failed-force writer closed");require(StorageMetrics.SYNC_CALLS.value.get()==1&&StorageMetrics.HASH_BYTES.value.get()==0&&StorageMetrics.STREAM_HASH_BYTES.value.get()==0,"failure never produced digest proof");StorageMetrics.finish();require(!new File(f.stage,"installed.manifest").exists(),"failed force cannot publish a receipt");require(file.delete(),"incomplete regular file removable for explicit retry");DownloadFile.copyStored(new ByteArrayInputStream(PAYLOAD),file,PAYLOAD.length,()->false,n->{});require(Arrays.equals(Files.readAllBytes(file.toPath()),PAYLOAD),"explicit retry writes correct complete bytes");}});
        test("canonical child remains owned under valid Windows short-root alias",()->{File root=new File(System.getProperty("java.io.tmpdir"),"localvoice-path-alias/models");File child=new File(root,"stage/file").getCanonicalFile();ModelFiles.requireOwnedPath(root,child);});
        test("POSIX read-only cancelled stage can be unlinked and explicitly retried",()->{try(Fixture f=new Fixture()){if(!Files.getFileStore(f.stage.toPath()).supportsFileAttributeView("posix"))throw new Skip("host has no POSIX permissions; Android0400 unlink/retry gate required");File file=f.file("retry.bin");Files.setPosixFilePermissions(file.toPath(),java.nio.file.attribute.PosixFilePermissions.fromString("r--------"));Files.delete(file.toPath());DownloadFile.copyStored(new ByteArrayInputStream(PAYLOAD),file,PAYLOAD.length,()->false,n->{});require(Arrays.equals(Files.readAllBytes(file.toPath()),PAYLOAD)&&!new File(f.stage,"installed.manifest").exists(),"read-only unadvertised file removed and full retry stays unverified");}});
        test("lexical file and ancestor symlinks cannot be verified or overwritten",()->{try(Fixture f=new Fixture();ModelFiles.FreshVerification job=f.job("r1")){File target=f.file("target");Path link=new File(f.stage,"link").toPath();try{Files.createSymbolicLink(link,target.toPath());}catch(UnsupportedOperationException|FileSystemException unavailable){throw new Skip("host cannot create symbolic links; Android NOFOLLOW gate required");}rejects(()->job.verifyFresh(link.toFile(),PAYLOAD.length,pin,()->false,n->{}));rejects(()->DownloadFile.copyStored(new ByteArrayInputStream(PAYLOAD),link.toFile(),PAYLOAD.length,()->false,n->{}));Path directory=new File(f.stage,"linked-dir").toPath();Files.createSymbolicLink(directory,f.stage.toPath());rejects(()->job.verifyFresh(new File(directory.toFile(),"target"),PAYLOAD.length,pin,()->false,n->{}));require(Arrays.equals(Files.readAllBytes(target.toPath()),PAYLOAD),"link target unchanged");}});
        System.out.println("Fresh verification checks: "+passed+" PASS, "+skipped+" SKIP; fake descriptor identities are not Android fstat evidence");
    }
}
